(function () {
  "use strict";

  var boostedSelectors = [
    "a[hx-boost='true']",
    "[hx-boost='true'] a[href]",
  ].join(",");

  function event(name, target, detail) {
    var payload = detail || {};
    payload.elt = target;
    var ev = new CustomEvent(name, {
      bubbles: true,
      cancelable: true,
      detail: payload,
    });
    target.dispatchEvent(ev);
    return ev;
  }

  function closest(el, selector) {
    return el && el.closest ? el.closest(selector) : null;
  }

  function hxValue(el, name) {
    var cur = el;
    while (cur && cur.nodeType === 1) {
      if (cur.hasAttribute(name)) return cur.getAttribute(name);
      cur = cur.parentElement;
    }
    return null;
  }

  function targetFor(el) {
    var selector = hxValue(el, "hx-target");
    if (!selector) return el;
    return document.querySelector(selector);
  }

  function swapContent(target, html, swap) {
    if (!target) return;
    if (swap === "outerHTML") {
      var wrap = document.createElement("template");
      wrap.innerHTML = html;
      var node = wrap.content.firstElementChild || document.createTextNode(html);
      target.replaceWith(node);
      runScripts(node.nodeType === 1 ? node : document.body);
      return;
    }
    target.innerHTML = html;
    runScripts(target);
  }

  function runScripts(root) {
    if (!root || !root.querySelectorAll) return;
    root.querySelectorAll("script").forEach(function (oldScript) {
      var script = document.createElement("script");
      script.async = false;
      Array.prototype.slice.call(oldScript.attributes).forEach(function (attr) {
        if (attr.name === "defer") return;
        script.setAttribute(attr.name, attr.value);
      });
      script.text = oldScript.text || oldScript.textContent || "";
      oldScript.replaceWith(script);
    });
  }

  async function request(opts) {
    var source = opts.source;
    var target = opts.target || targetFor(source);
    if (!target) return;
    var swap = opts.swap || hxValue(source, "hx-swap") || "innerHTML";
    var before = event("htmx:beforeRequest", source, { target: target });
    if (before.defaultPrevented) return;

    var init = {
      method: opts.method || "GET",
      credentials: "same-origin",
      headers: {
        "HX-Request": "true",
      },
    };
    if (opts.body) init.body = opts.body;
    var response = await fetch(opts.url, init);
    var html = await response.text();
    if (!response.ok) {
      event("htmx:responseError", source, { target: target, xhr: response });
      throw new Error("Request failed: " + response.status);
    }
    var beforeSwap = event("htmx:beforeSwap", target, {
      target: target,
      xhr: response,
      serverResponse: html,
    });
    if (beforeSwap.defaultPrevented) return;
    swapContent(target, html, swap);
    process(document);
    event("htmx:afterSwap", target, {
      target: target,
      xhr: response,
      serverResponse: html,
    });
    return true;
  }

  function hydrate(node) {
    var url = node.getAttribute("hx-get");
    if (!url) return Promise.resolve();
    return request({
      source: node,
      target: node,
      url: url,
      method: "GET",
      swap: node.getAttribute("hx-swap") || "innerHTML",
    }).catch(function () {});
  }

  function wire(node) {
    if (!node || node.__mhHtmxWired) return;
    node.__mhHtmxWired = true;
    var trigger = node.getAttribute("hx-trigger") || "";
    if (!trigger || trigger.indexOf("load") !== -1) hydrate(node);
    var match = trigger.match(/every\s+(\d+)s/);
    if (match) {
      var seconds = Number(match[1]);
      if (seconds > 0) {
        window.setInterval(function () { hydrate(node); }, seconds * 1000);
      }
    }
  }

  function process(root) {
    (root || document).querySelectorAll("[hx-get]").forEach(wire);
  }

  document.addEventListener("click", function (e) {
    var button = closest(e.target, "[hx-post]");
    if (button) {
      e.preventDefault();
      request({
        source: button,
        target: targetFor(button),
        url: button.getAttribute("hx-post"),
        method: "POST",
        swap: hxValue(button, "hx-swap") || "innerHTML",
      }).catch(function () {});
      return;
    }

    var link = closest(e.target, boostedSelectors);
    if (!link || link.target || link.hasAttribute("download")) return;
    if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    var url = link.href;
    if (!url || new URL(url, window.location.href).origin !== window.location.origin) return;
    e.preventDefault();
    request({
      source: link,
      target: targetFor(link),
      url: url,
      method: "GET",
      swap: hxValue(link, "hx-swap") || "innerHTML",
    }).then(function (swapped) {
      if (!swapped) return;
      window.history.pushState({ mhHtmx: true }, "", url);
      event("htmx:pushedIntoHistory", link, { path: url });
    }).catch(function () {
      window.location.assign(url);
    });
  });

  window.addEventListener("popstate", function () {
    var target = document.querySelector("#page-content");
    if (!target) return;
    request({
      source: target,
      target: target,
      url: window.location.href,
      method: "GET",
      swap: "innerHTML",
    }).then(function () {
      event("htmx:historyRestore", target, { path: window.location.href });
    }).catch(function () {
      window.location.reload();
    });
  });

  window.htmx = window.htmx || {};
  window.htmx.version = window.htmx.version || "mystic-tiny";
  window.htmx.process = process;
  window.htmx.ajax = function (method, url, options) {
    options = options || {};
    var source = options.source || document.body;
    return request({
      source: source,
      target: typeof options.target === "string" ? document.querySelector(options.target) : options.target,
      url: url,
      method: method || "GET",
      swap: options.swap || "innerHTML",
      body: options.body || null,
    });
  };

  window.addEventListener("DOMContentLoaded", function () {
    process(document);
  });
})();
